using System.Collections.Generic;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "InvokeAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/Invoke Action")]
public class InvokeAction : ChaoticAction
{
	[Header("Assets")]
	[SerializeField]
	private GameObject diceInstance3DPrefab;

	[SerializeField]
	private ActionInstanceData playerActionInstanceData;

	[SerializeField]
	private RerollAction rerollAction;

	[Header("Dice")]
	[SerializeField]
	private bool removeAfterBattle;

	[SerializeField]
	[HideIf("removeAfterBattle")]
	private PlayerDiceInventoryData dicePool;

	[SerializeField]
	private bool enableSpecificDice;

	[SerializeField]
	[ShowIf("enableSpecificDice")]
	private string specificDiceName;

	[SerializeField]
	[ShowIf("enableSpecificDice")]
	private Tag specificDiceTag;

	[SerializeField]
	[ShowIf("enableSpecificDice")]
	private AllPlayerDicesList allPlayerDicesList;

	[SerializeField]
	private bool enableSpecificDiceTier;

	[SerializeField]
	[ShowIf("enableSpecificDiceTier")]
	private DiceTier specificDiceTier;

	[Header("Invoke")]
	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	[SerializeField]
	private bool destroyDieAfterInvoking;

	[SerializeField]
	private bool invokedDieWontStayOnDrawPoolForTheRestOfTheBattle;

	[SerializeField]
	private bool dontGetOtherTiersDiscover;

	[SerializeField]
	private bool enableExtraAction;

	[SerializeField]
	[ShowIf("enableExtraAction")]
	private BattleAction extraBattleAction;

	[SerializeField]
	[ShowIf("enableExtraAction")]
	private int extraActionValue;

	[SerializeField]
	[ShowIf("enableExtraAction")]
	private OmenLogic extraActionOmenLogic;

	public Tag SpecificDiceTag => specificDiceTag;

	public bool DestroyDieAfterInvoking => destroyDieAfterInvoking;

	public bool InvokedDieWontStayOnDrawPoolForTheRestOfTheBattle => invokedDieWontStayOnDrawPoolForTheRestOfTheBattle;

	public bool EnableExtraAction => enableExtraAction;

	public BattleAction ExtraBattleAction => extraBattleAction;

	public int ExtraActionValue => extraActionValue;

	public override void CastAmount(int amount, GameObject source)
	{
		DefaultCast(source, amount);
	}

	public override void Cast(GameObject source)
	{
		DefaultCast(source, 1);
	}

	private void DefaultCast(GameObject source, int diceAmount)
	{
		Dice dice = new Dice();
		if (enableExtraAction)
		{
			extraActionOmenLogic.ActivateOmen(extraBattleAction, extraActionValue, null, source);
		}
		if (enableSpecificDice)
		{
			dice = allPlayerDicesList.GetDice(specificDiceName);
		}
		else if (enableSpecificDiceTier)
		{
			List<Dice> list = new List<Dice>();
			list = dicesRewardsListsList.GetCurrentCharacterUnlockedDiceTierDiceList(specificDiceTier).diceList.Duplicate();
			list.AddRange(dicesRewardsListsList.GetAnyCharacterUnlockedDiceTierDiceList(specificDiceTier).diceList.Duplicate());
			ReferenceSingleton<AssetsReference>.Instance.DiceReward.RemoveCharactersAndChapterMutedDiceFromList(list);
			dice = list.PickRandom();
		}
		else
		{
			dice = GetRandomDice();
		}
		if (!removeAfterBattle)
		{
			dicePool.IncreaseDiceAmount(dice, 1, insertAsFirst: false, updateDicePoolText: true, triggerOnDieAddedToDicePoolEvents: true);
		}
		CheckDiceDiscovered(dice);
		Spawn3DDice(dice, diceAmount);
		if (source == ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject && destroyDieAfterInvoking)
		{
			(ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance as DiceInstance).DestroyDiceDisposeAction();
		}
	}

	private void CheckDiceDiscovered(Dice dicePicked)
	{
		if ((dicePicked as PlayerDice).CompendiumItemState == CompendiumItemState.Undiscovered)
		{
			List<Dice> list = new List<Dice>();
			list.Add(dicePicked);
			dicesRewardsListsList.DiceDiscovered(list, dontGetOtherTiersDiscover);
		}
	}

	public void Spawn3DDice(Dice dicePicked, int diceAmount = 1, bool enableExternalRemoveAfterBattle = false, bool externalRemoveAfterBattle = false)
	{
		List<DiceInstance> list = new List<DiceInstance>();
		for (int i = 0; i < diceAmount; i++)
		{
			Dice dice = dicePicked.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
			Dice dice2 = dice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
			dice.RemoveAfterBattle = (enableExternalRemoveAfterBattle ? externalRemoveAfterBattle : removeAfterBattle);
			dice2.RemoveAfterBattle = dice.RemoveAfterBattle;
			GameObject @object = ReferenceSingleton<PoolHandler>.Instance.GetObject(diceInstance3DPrefab.name, ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.transform.position.ZeroZ() + Vector3.right * 0.5f);
			int num = -1;
			for (int j = 0; j < dice.GetDiceFaces().Length; j++)
			{
				DiceFace diceFace = dice.GetDiceFaces()[j];
				if (diceFace.BattleAction is ChaoticAction && !(diceFace.BattleAction is InvokeAction))
				{
					num = j;
					break;
				}
			}
			if (num > -1)
			{
				DiceFace[] array = (dice.GetDiceFaces()[num].BattleAction as ChaoticAction).GetRandomDice().CopyDiceFacesAsNewInstances();
				for (int k = 0; k < array.Length; k++)
				{
					DiceFace diceFace2 = dice.GetDiceFaces()[k];
					if (!(diceFace2.BattleAction is ChaoticAction))
					{
						array[k] = diceFace2;
					}
					else if (diceFace2.BattleAction is InvokeAction)
					{
						array[k] = diceFace2;
					}
				}
				dice.SetDiceFaces(array);
			}
			dice.ToggleActionValueModifier(ReferenceSingleton<PlayerDiceHandHolder>.Instance.ActionValueModifiers);
			DiceInstance component = @object.GetComponent<DiceInstance>();
			component.SetOriginalDice(dice2);
			ReferenceSingleton<PlayerDiceHandHolder>.Instance.AddDiceInstanceToHand(component, dice);
			component.Initialize(dice, playerActionInstanceData, playerGameObjectReference.value);
			list.Add(component);
		}
		ReferenceSingleton<DiceRollingHandler>.Instance.RollDieWithDieSetup(list);
	}
}
